void wake_init(void)
{
    static Boolean do_one_time = TRUE ;

    if( do_one_time )
    {
        per_exec_register((Per_Exec_Func)wake_state);
        
        wake_vars.counter1 = 0 ; 
        wake_vars.counter2 = 0 ; 
        wake_vars.timeout  = WAKE_TIMEOUT1;
        wake_vars.timeout1 = WAKE_TIMEOUT1;
        wake_vars.timeout2 = WAKE_TIMEOUT2;     
				wake_going_sleep = FALSE;
        
        ATOMIC(do_one_time = FALSE);
    }        	
}

